CREATE INDEX ix_ts ON ev(ts);

EXPLAIN QUERY PLAN
SELECT COUNT(*) FROM ev WHERE ts >= '2026-01-01' AND ts < '2026-02-01';
-- SEARCH ev USING COVERING INDEX ix_ts (ts>? AND ts<?)

EXPLAIN QUERY PLAN
SELECT COUNT(*) FROM ev WHERE substr(ts, 1, 7) = '2026-01';
